{{!-- Styling parameters: class, imageClass, contentClass, titleClass, descriptionClass, metaClass, footerClass --}}
{{#with this as |ghostcnStyles|}}
{{!--
  Component: Post Card
  Usage: Inside {{#foreach posts}} ... {{> "components/post-card"}} ... {{/foreach}}
--}}
<article class="gh-post-card{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}} group">
    {{#if feature_image}}
    <a href="{{url}}" class="gh-post-card-image">
        <img src="{{img_url feature_image size="m"}}" alt="{{#if feature_image_alt}}{{feature_image_alt}}{{else}}{{title}}{{/if}}" class="gh-post-card-img{{#if ghostcnStyles.imageClass}} {{ghostcnStyles.imageClass}}{{/if}}" loading="lazy" />
    </a>
    {{/if}}

    <div class="gh-post-card-content{{#if ghostcnStyles.contentClass}} {{ghostcnStyles.contentClass}}{{/if}}">
        <div>
            <div class="gh-post-card-meta{{#if ghostcnStyles.metaClass}} {{ghostcnStyles.metaClass}}{{/if}}">
                {{#if primary_tag}}
                <a href="{{primary_tag.url}}" class="gh-post-card-tag">{{primary_tag.name}}</a>
                <span class="gh-post-card-separator">&bull;</span>
                {{/if}}
                <span class="gh-post-card-reading-time">{{reading_time}}</span>
            </div>

            <h3 class="gh-post-card-title{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">
                <a href="{{url}}">{{title}}</a>
            </h3>

            {{#if excerpt}}
            <p class="gh-post-card-excerpt{{#if ghostcnStyles.descriptionClass}} {{ghostcnStyles.descriptionClass}}{{/if}}">{{excerpt words="25"}}</p>
            {{/if}}
        </div>

        <div class="gh-post-card-footer{{#if ghostcnStyles.footerClass}} {{ghostcnStyles.footerClass}}{{/if}}">
            <div class="gh-post-card-author">
                {{#primary_author}}
                <span>{{name}}</span>
                {{/primary_author}}
            </div>
            <time datetime="{{date format="YYYY-MM-DD"}}">{{date format="D MMM YYYY"}}</time>
        </div>
    </div>
</article>
{{/with}}

/* ghostcn: Post Card Styles */
.gh-post-card {
    box-sizing: border-box; min-width: 0; overflow-wrap: anywhere; border: 1px solid var(--border, #e4e4e7); border-radius: var(--ghcn-panel-radius, min(var(--radius, 8px), 24px)); background: var(--card, #fff); color: var(--card-foreground, #09090b);
    font-family: inherit;
    font-size: var(--ghcn-text-body, 16px);
    line-height: 1.5;
    isolation: isolate;
    overflow: hidden;
    display: flex;
    flex-direction: column;
}

.gh-post-card *,
.gh-post-card *::before,
.gh-post-card *::after {
    box-sizing: border-box;
}

.gh-post-card-image {
    aspect-ratio: 16 / 9;
    overflow: hidden;
    display: block;
    background-color: var(--muted, #f4f4f5);
}

.gh-post-card-image img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.gh-post-card-content {
    padding: var(--ghcn-panel-padding, clamp(16px, 3vw, 24px));
    flex: 1;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
}

.gh-post-card-tag {
    color: inherit;
    font-size: inherit;
    font-weight: 600;
    text-decoration: none;
}

.gh-post-card-tag:hover {
    text-decoration: underline;
}

.gh-post-card-title {
    font-size: var(--ghcn-title-card, 20px); font-weight: 650; line-height: 1.3; letter-spacing: -.025em; color: inherit;
    margin: 8px 0;
}

.gh-post-card-title a {
    color: inherit;
    text-decoration: none;
    transition: color 0.15s ease;
}

.gh-post-card-title a:hover {
    text-decoration: underline;
    text-underline-offset: 3px;
}

.gh-post-card-excerpt {
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 3;
    overflow: hidden;
    color: var(--muted-foreground, #71717a);
    font-size: var(--ghcn-text-small, 14px);
    line-height: 1.5;
    margin: 0 0 16px;
}

.gh-post-card-footer {
    padding-top: 1em;
    border-top: 1px solid var(--border, #e4e4e7);
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 4px 12px;
    font-size: var(--ghcn-text-meta, 13px);
    color: var(--muted-foreground, #71717a);
}

.gh-post-card-meta { display: flex; align-items: center; flex-wrap: wrap; gap: 8px; margin-bottom: 8px; color: var(--muted-foreground); font-size: var(--ghcn-text-meta, 13px); }
.gh-post-card-reading-time { color: var(--muted-foreground); }
.gh-post-card-separator { color: color-mix(in srgb, var(--muted-foreground) 40%, transparent); }
.gh-post-card-author { display: flex; align-items: center; gap: 0.5em; font-weight: 500; }
.gh-post-card:focus-visible, :where(.gh-post-card) :focus-visible { outline: 2px solid var(--ring, currentColor); outline-offset: 2px; }
.gh-post-card-image:focus-visible { outline-offset: -3px; }
